import random,itertools,json,subprocess,sys,math
from fractions import Fraction

G=((0,0,1),(1,1,2),(1,1,2))
def canon(a,b): return (a,b) if a<b else (b,a)
def norm(p,ixps):
 out=[]
 for x in p:
  if x in ixps: continue
  if not out or out[-1]!=x: out.append(x)
 return tuple(out)
def peel(paths):
 cur=dict(paths); rounds={}; r=1
 while True:
  marked=set()
  edges={canon(a,b) for p in cur for a,b in zip(p,p[1:])}
  for u,v in edges:
   cont=[p for p in cur if any(canon(a,b)==(u,v) for a,b in zip(p,p[1:]))]
   if all(p[0]==u or p[-1]==u for p in cont) or all(p[0]==v or p[-1]==v for p in cont):
    marked.add((u,v))
  if not marked: break
  for e in marked: rounds[e]=r
  new={}
  for p,c in cur.items():
   fm=canon(p[0],p[1]) in marked
   lm=canon(p[-2],p[-1]) in marked
   q=p[1 if fm else 0: len(p)-(1 if lm else 0)]
   if len(q)>=2: new[q]=new.get(q,0)+c
  cur=new;r+=1
 core={canon(a,b) for p in cur for a,b in zip(p,p[1:])}
 return rounds,cur,core

