  if len(p)<2 or len(set(p))!=len(p): continue
  agg[p]=agg.get(p,0)+rec['count']
  for a,b in zip(p,p[1:]): all_edges.add(canon(a,b))
 rounds,cp,core=peel(agg)
 edges=sorted(core); m=len(edges); ei={e:i for i,e in enumerate(edges)}
 # factor per assignment direct
 Z=0; N=[[0,0,0] for _ in range(m)]
 for states in itertools.product(range(3),repeat=m):
  W=1
  for ci,e in enumerate(edges):
   u,v=e; phi=0
   for p,c in cp.items():
    for j,(a,b) in enumerate(zip(p,p[1:])):
     if canon(a,b)!=e: continue
     if a==u:
      q=list(p); pos=j
     else:
      q=list(reversed(p)); pos=len(p)-2-j
     assert q[pos]==u and q[pos+1]==v
     def typ(w,dest):
      f=canon(w,dest); fi=ei[f]
      st=states[fi]
      return 2-st if w>dest else st
     L=0 if pos==0 else typ(q[pos-1],u)
     R=2 if pos+2==len(q) else typ(v,q[pos+2])
     if states[ci]==G[L][R]: phi+=c
   W*=phi
  if W:
