   for i,t in enumerate(states): N[i][t]+=W
 if Z==0: return {'error':'zero-partition'}
 marg={e:tuple(Fraction(N[i][t],Z) for t in range(3)) for i,e in enumerate(edges)}
 prior={}
 for rec in data['priors']:
  u,v=rec['link']; w=rec['weights']; ss=sum(w)
  vec=tuple(Fraction(x,ss) for x in w)
  if u>v: vec=vec[::-1]
