  if u>v: vec.reverse()
  decl[canon(u,v)]=tuple(vec)
 unif=(Fraction(1,3),)*3
 links=[]
 for e in sorted(all_edges):
  if e in ei: rr=0; pv=marg[e]
  else: rr=rounds[e]; pv=prior.get(e,unif)
  links.append({'link':[e[0],e[1]],'round':rr,'prob':[float(x) for x in pv]})
 qout=[]
 for rec in data['queries']:
