def find_order(edges,sc):
 m=len(edges)
 # brute, small
 for perm in itertools.permutations(range(m)):
  adj=[set() for _ in range(m)]
  for s in sc:
   ss=list(s)
   for i in range(len(ss)):
    for j in range(i+1,len(ss)):
     adj[ss[i]].add(ss[j]);adj[ss[j]].add(ss[i])
  ok=True
  for x in perm:
   if len(adj[x])>4: ok=False;break
   ne=list(adj[x])
   for i in range(len(ne)):
    for j in range(i+1,len(ne)):
     adj[ne[i]].add(ne[j]);adj[ne[j]].add(ne[i])
   for y in ne: adj[y].discard(x)
   adj[x].clear()
  if ok: return [list(edges[x]) for x in perm]
 return None

